// Page backgrounds (M10a): curated colour swatches, our own generated textures, and the
// Background union stored in the book document. Pure and client-safe: shared by editor, viewer,
// print and the AI pipeline. Texture files are generated by scripts/gen-textures.mjs (CC0, see
// public/design/LICENSE.md) and served same-origin from /design/textures/ — the print renderer
// only allows the app's own origin (src/lib/pdf/request-routing.ts).
//
// The doc schema (src/lib/book/schema.ts) imports the constants (veil range, texture ids) from this
// module; the Background types come from that schema (re-exported below).

import type { Background } from "@/lib/book/types";

export type Orientation = "portrait" | "landscape";
export type Ink = "dark" | "light";

/** Text colour per ink. `dark` matches the caption colour in BookPage (text-neutral-800). */
export const INK_COLORS: Record<Ink, string> = { dark: "#262626", light: "#FFFFFF" };

// --- Background union (doc v2) -------------------------------------------------------------------

export const BACKGROUND_VEIL_MIN = 0.5;
export const BACKGROUND_VEIL_MAX = 0.9;
export const DEFAULT_BACKGROUND_VEIL = 0.75;
export const DEFAULT_VEIL_COLOR = "#FFFFFF";

// The union's TS types are inferred from the zod schema in src/lib/book/schema.ts (one source);
// re-exported here so catalogue users can import them from lib/design. Type-only: no runtime cycle
// (schema.ts imports this module's constants).
export type { Background };
export type ColorBackground = Extract<Background, { kind: "color" }>;
export type TextureBackground = Extract<Background, { kind: "texture" }>;
export type PhotoBackground = Extract<Background, { kind: "photo" }>;

export const DEFAULT_BACKGROUND: ColorBackground = { kind: "color", hex: "#FFFFFF" };

const HEX_RE = /^#[0-9A-Fa-f]{6}$/;
export function isHexColor(v: unknown): v is string {
  return typeof v === "string" && HEX_RE.test(v);
}

// --- colour swatches -----------------------------------------------------------------------------

export interface BackgroundSwatch {
  id: string;
  hex: string;
  /** Text colour that reads on this background (≥ 4.5:1, enforced by tests). */
  ink: Ink;
  label: string;
}

export const BACKGROUND_SWATCHES = [
  { id: "white", hex: "#FFFFFF", ink: "dark", label: "White" },
  { id: "cream", hex: "#F5EEDC", ink: "dark", label: "Cream" },
  { id: "warm-sand", hex: "#E6D5B8", ink: "dark", label: "Warm sand" },
  { id: "blush", hex: "#F2D4CF", ink: "dark", label: "Blush" },
  { id: "butter", hex: "#F5E6AE", ink: "dark", label: "Butter" },
  { id: "sage", hex: "#CAD6C1", ink: "dark", label: "Sage" },
  { id: "sky", hex: "#CFE1F0", ink: "dark", label: "Sky" },
  { id: "lavender", hex: "#DDD5EA", ink: "dark", label: "Lavender" },
  { id: "stone", hex: "#CFCBC4", ink: "dark", label: "Stone" },
  { id: "terracotta", hex: "#A65A3F", ink: "light", label: "Terracotta" },
  { id: "olive", hex: "#55603A", ink: "light", label: "Olive" },
  { id: "teal", hex: "#235A5E", ink: "light", label: "Teal" },
  { id: "navy", hex: "#1E2A47", ink: "light", label: "Navy" },
  { id: "burgundy", hex: "#6A2333", ink: "light", label: "Burgundy" },
  { id: "charcoal", hex: "#34373C", ink: "light", label: "Charcoal" },
  { id: "black", hex: "#111111", ink: "light", label: "Black" },
] as const satisfies readonly BackgroundSwatch[];

export type SwatchId = (typeof BACKGROUND_SWATCHES)[number]["id"];

export function swatchById(id: string): BackgroundSwatch | undefined {
  return BACKGROUND_SWATCHES.find((s) => s.id === id);
}

// --- textures ------------------------------------------------------------------------------------

export const TEXTURE_DIR = "/design/textures";

/**
 * Physical size of one tile in print. The print JPEG is 512 px → 512 / (40 / 25.4) = 325 dpi.
 * On screen, render the tile at the same physical size relative to the page
 * (background-size = TILE_MM / pageWidthMm × page width).
 */
export const TEXTURE_TILE_MM = 40;

export interface Texture {
  id: string;
  label: string;
  /**
   * tile: seamless, repeat at tileMm. wash: one full sheet per orientation (incl. bleed,
   * 154×216 / 216×154 mm), stretch with background-size: cover.
   */
  kind: "tile" | "wash";
  /** webp for editor/viewer, per orientation (tiles: same file for both). */
  screenSrc: Record<Orientation, string>;
  /** JPEG for the print renderer (passes through to the PDF without re-encoding). */
  printSrc: Record<Orientation, string>;
  tileMm?: number;
  ink: Ink;
  /** Mean colour of the texture: fallback while loading / if the file fails. */
  baseHex: string;
}

function tile(id: string, label: string, baseHex: string, ink: Ink): Texture {
  const screen = `${TEXTURE_DIR}/${id}.webp`;
  const print = `${TEXTURE_DIR}/${id}.jpg`;
  return {
    id,
    label,
    kind: "tile",
    screenSrc: { portrait: screen, landscape: screen },
    printSrc: { portrait: print, landscape: print },
    tileMm: TEXTURE_TILE_MM,
    ink,
    baseHex,
  };
}

function wash(id: string, label: string, baseHex: string, ink: Ink): Texture {
  const f = (o: Orientation, ext: string) => `${TEXTURE_DIR}/${id}-${o}.${ext}`;
  return {
    id,
    label,
    kind: "wash",
    screenSrc: { portrait: f("portrait", "webp"), landscape: f("landscape", "webp") },
    printSrc: { portrait: f("portrait", "jpg"), landscape: f("landscape", "jpg") },
    ink,
    baseHex,
  };
}

export const TEXTURES = [
  tile("paper-cream", "Cream paper", "#EEE5D3", "dark"),
  tile("paper-white", "White paper", "#F1F0EC", "dark"),
  tile("linen", "Linen", "#D6CAB8", "dark"),
  tile("kraft", "Kraft", "#BB966A", "dark"),
  wash("watercolour-blush", "Blush watercolour", "#F5E9E3", "dark"),
  wash("watercolour-sky", "Sky watercolour", "#E6ECF0", "dark"),
] as const satisfies readonly Texture[];

export const TEXTURE_IDS = [
  "paper-cream",
  "paper-white",
  "linen",
  "kraft",
  "watercolour-blush",
  "watercolour-sky",
] as const;
export type TextureId = (typeof TEXTURE_IDS)[number];

export function isKnownTextureId(v: unknown): v is TextureId {
  return typeof v === "string" && (TEXTURE_IDS as readonly string[]).includes(v);
}

export function textureById(id: string): Texture | undefined {
  return (TEXTURES as readonly Texture[]).find((t) => t.id === id);
}

export function textureSrc(t: Texture, orientation: Orientation, target: "screen" | "print"): string {
  return (target === "print" ? t.printSrc : t.screenSrc)[orientation];
}

// --- contrast ------------------------------------------------------------------------------------

function channelToLinear(c: number): number {
  const s = c / 255;
  return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
}

function rgb(hex: string): [number, number, number] {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/** WCAG relative luminance of #RRGGBB. */
export function relativeLuminance(hex: string): number {
  const [r, g, b] = rgb(hex).map(channelToLinear);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** WCAG contrast ratio between two #RRGGBB colours (1..21). */
export function contrastRatio(a: string, b: string): number {
  const la = relativeLuminance(a);
  const lb = relativeLuminance(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

/** The ink with the higher contrast on a plain colour. */
export function inkForHex(hex: string): Ink {
  if (!isHexColor(hex)) return "dark";
  return contrastRatio(hex, INK_COLORS.dark) >= contrastRatio(hex, INK_COLORS.light) ? "dark" : "light";
}

/** Multiply blend of two #RRGGBB colours (used for tinted textures). */
export function multiplyHex(a: string, b: string): string {
  const [ar, ag, ab] = rgb(a);
  const [br, bg, bb] = rgb(b);
  return (
    "#" +
    [ar * br, ag * bg, ab * bb]
      .map((v) => Math.round(v / 255).toString(16).padStart(2, "0"))
      .join("")
      .toUpperCase()
  );
}

/**
 * Text ink for a background. Colour: computed from luminance. Texture: declared ink, or computed
 * from the tinted base colour when a tint is set. Photo: the veil colour decides (the veil is at
 * least 50 % opaque). Unknown/malformed input → dark.
 */
export function inkFor(background: Background | string | null | undefined): Ink {
  if (!background) return "dark";
  if (typeof background === "string") return inkForHex(background); // v1 style.background
  switch (background.kind) {
    case "color":
      return inkForHex(background.hex);
    case "texture": {
      const t = textureById(background.textureId);
      if (!t) return "dark";
      return background.tint && isHexColor(background.tint)
        ? inkForHex(multiplyHex(t.baseHex, background.tint))
        : t.ink;
    }
    case "photo":
      return inkForHex(background.veilColor);
    default:
      return "dark";
  }
}
